import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        // Bit c of a mask: character c occurs an odd number of times.
        int total = 0;
        for (int i = 0; i < s.length(); i++) total ^= 1 << (s.charAt(i) - 'a');
        // A part works iff it has at most 2 odd-count characters (one deletion fixes one).
        int left = 0;
        for (int i = 0; i + 1 < s.length(); i++) {
            left ^= 1 << (s.charAt(i) - 'a');
            if (Integer.bitCount(left) <= 2 && Integer.bitCount(total ^ left) <= 2) {
                System.out.println("YES");
                return;
            }
        }
        System.out.println("NO");
    }
}

package main

import (
	"fmt"
	"io"
	"math/bits"
	"os"
)

var data []byte
var pos int

func nextToken() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := nextToken()
	// Bit c of a mask: character c occurs an odd number of times.
	var total uint32
	for _, c := range s {
		total ^= 1 << (c - 'a')
	}
	// A part works iff it has at most 2 odd-count characters (one deletion fixes one).
	var left uint32
	for i := 0; i+1 < len(s); i++ {
		left ^= 1 << (s[i] - 'a')
		if bits.OnesCount32(left) <= 2 && bits.OnesCount32(total^left) <= 2 {
			fmt.Println("YES")
			return
		}
	}
	fmt.Println("NO")
}
